#!/usr/bin/env node
/* JS-side golden test runner.
 *
 * Compares the JS interpreter (pxscript.js) for every tests/cases/*.pxs
 * against its *.expected.json (generated by tests/gen_expected.py via the
 * Python DSL). Run:  node tests/run_js.js
 */
const fs = require("fs");
const path = require("path");
const Pxs = require(path.join(__dirname, "..", "pxscript.js"));

const casesDir = path.join(__dirname, "cases");
const cases = fs.readdirSync(casesDir)
  .filter(f => f.endsWith(".pxs"))
  .sort();

if (cases.length === 0) {
  console.error("no cases found");
  process.exit(1);
}

let failed = 0;
for (const file of cases) {
  const caseFile = path.join(casesDir, file);
  const expected = JSON.parse(
    fs.readFileSync(caseFile.replace(/\.pxs$/, ".expected.json"), "utf8"));
  const r = Pxs.run(fs.readFileSync(caseFile, "utf8"), null, { requireCanvas: true });
  let got = null;
  if (r.ok) {
    const img = r.img;
    got = {
      name: img.name,
      width: img.width,
      height: img.height,
      frameWidth: img.frameWidth,
      frameHeight: img.frameHeight,
      pixels: img.pixels,
      warnings: r.warnings,
    };
  }
  if (got === null) {
    console.log(`FAIL ${file}: raised ${r.error}`);
    failed++;
    continue;
  }
  if (JSON.stringify(got) === JSON.stringify(expected)) {
    console.log(`pass ${file}`);
  } else {
    console.log(`FAIL ${file}`);
    for (const key of ["name", "width", "height", "frameWidth", "frameHeight", "pixels", "warnings"]) {
      if (JSON.stringify(got[key]) !== JSON.stringify(expected[key])) {
        console.log(`  field ${key} differs`);
      }
    }
    failed++;
  }
}
console.log(`total: ${cases.length}, failed: ${failed}`);
process.exit(failed === 0 ? 0 : 1);
